CREATE OR REPLACE FUNCTION private.dic_admin_set_member_access(p_member_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();m private.beta_members;found_member uuid;
begin
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator access required.';
 end if;
 if p_member_id is null or p_enabled is null then
  raise exception using errcode='22023',message='Member and desired access are required.';
 end if;
 -- Never allow an administrator to revoke themself OR ANY administrator.
 -- The underlying permanent admin role has no expiration.
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts cannot be removed here.';
 end if;
 -- Permanently deleting a member supersedes reversible Restore/Remove.
 if exists(select 1 from private.dic_admin_account_delete_operations
   where target_id=p_member_id and phase<>'completed') then
  raise exception using errcode='23514',message='Permanent deletion is underway; finish it before changing access.';
 end if;
 select * into m from private.beta_members where owner_id=p_member_id for update;
 if not found or m.admitted_at is null then
  raise exception using errcode='22023',message='Only previously admitted members can be changed.';
 end if;
 if p_enabled and not exists(select 1 from auth.users where id=p_member_id and email_confirmed_at is not null) then
  raise exception using errcode='42501',message='Verified email required.';
 end if;
 if m.enabled=p_enabled then
  return jsonb_build_object('ok',true,'enabled',p_enabled,'unchanged',true);
 end if;
 update private.beta_members set enabled=p_enabled
 where owner_id=p_member_id returning owner_id into found_member;
 insert into private.admin_access_events(actor_id,action,member_id)
 values(actor,case when p_enabled then 'restore_access' else 'remove_access' end,found_member);
 -- No auth.users deletion, note deletion, contribution identity reidentification,
 -- historical mutation, or implicit sign-out of already issued Supabase tokens.
 -- All member RPCs and RLS must recheck private.is_member().
 return jsonb_build_object('ok',true,'enabled',p_enabled);
end $function$

CREATE OR REPLACE FUNCTION private.dic_source_key(value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare raw text; path text; params text; kept text:=''; part text;
begin
 raw:=btrim(coalesce(value,''));
 if raw !~* '^https?://[^/?#[:space:]]+' or length(raw)>4000 then return null;end if;
 raw:=split_part(raw,'#',1);
 raw:=regexp_replace(raw,'^https?://(www\.)?','','i');
 path:=split_part(raw,'?',1);
 if path='' then return null;end if;
 params:=case when strpos(raw,'?')>0 then substring(raw from strpos(raw,'?')+1) else '' end;
 if params<>'' then
  foreach part in array string_to_array(params,'&') loop
   if split_part(lower(part),'=',1)!~'^utm_' and
     lower(split_part(part,'=',1)) not in ('gclid','fbclid','msclkid','srsltid')
       and part<>'' then
    kept:=concat_ws('&',nullif(kept,''),part);
   end if;
  end loop;
 end if;
 return lower(rtrim(path,'/'))||case when kept<>'' then '?'||kept else '' end;
end $function$

CREATE OR REPLACE FUNCTION private.dic_submit_coffee_auto(mid uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.require_member(); prior private.mutation_receipts;
 req_hash text; proposal jsonb; source text; lid uuid; sid uuid; match_result jsonb;
 exact uuid; existing uuid; response jsonb; managed_name text;
begin
 if mid is null or jsonb_typeof(p) is distinct from 'object'
 or octet_length(p::text)>32000 or jsonb_typeof(p->'proposed_data') is distinct from 'object'
 or coalesce(length(btrim(p->'proposed_data'->>'name')),0) not between 1 and 200
 or coalesce(length(btrim(p->'proposed_data'->>'roaster')),0) not between 2 and 200 then
  raise exception using errcode='22023',message='Coffee name and roaster are required.';
 end if;
 source:=nullif(btrim(p->>'source_url'),'');
 if source is not null and (length(source)>4000 or source !~ '^https?://') then
  raise exception using errcode='22023',message='Provide a valid product URL.';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,9311));
 req_hash:=encode(sha256(convert_to(jsonb_build_object('action','submit_coffee','payload',p)::text,'UTF8')),'hex');
 select * into prior from private.mutation_receipts where owner_id=u and mutation_id=mid;
 if found then
  if prior.request_hash<>req_hash then raise exception using errcode='22023',message='Mutation ID reused for different changes.';end if;
  return prior.response;
 end if;
 proposal:=p->'proposed_data';
 match_result:=private.dic_find_coffee_matches(proposal||jsonb_build_object('source_url',source));
 if match_result->>'classification'='exact_verified' then
  exact:=(match_result->>'exact_id')::uuid;
  select id into existing from public.library_entries where owner_id=u and coffee_id=exact and hidden_at is null order by created_at limit 1;
  if existing is null then
   lid:=coalesce((p->>'library_entry_id')::uuid,gen_random_uuid());
   insert into public.library_entries(id,owner_id,coffee_id) values(lid,u,exact);
  else lid:=existing; end if;
  response:=jsonb_build_object('ok',true,'status','verified','coffee_id',exact,'library_entry_id',lid,'reused',true);
 else
  lid:=coalesce((p->>'library_entry_id')::uuid,gen_random_uuid());
  managed_name:=nullif(match_result->'roaster'->>'canonical_name','');
  if coalesce((match_result->'roaster'->>'recognized')::boolean,false) and managed_name is not null
      and managed_name<>proposal->>'roaster' then
   proposal:=jsonb_set(proposal,'{roaster_as_entered}',to_jsonb(proposal->>'roaster'),true);
   proposal:=jsonb_set(proposal,'{roaster}',to_jsonb(managed_name),true);
  end if;
  insert into public.coffee_submissions(owner_id,proposed_data,source_url,created_at) values(u,proposal,source,clock_timestamp())
   returning id into sid;
  insert into public.library_entries(id,owner_id,submission_id) values(lid,u,sid);
  response:=jsonb_build_object('ok',true,'status','pending','library_entry_id',lid,
    'submission_id',sid,'source_check_recommended',
      (source is not null and coalesce((match_result->'roaster'->>'recognized')::boolean,false)));
  if match_result->>'classification'='needs_confirmation' then
   -- User confirmed_distinct never bypasses server duplicate gates.
   response:=response||jsonb_build_object('possible_duplicate',true,
     'candidates',match_result->'candidates');
  else
   response:=response||private.dic_promote_pending_coffee(sid,'member_auto_approved',
    jsonb_build_object('approval_basis','no_unresolved_duplicate',
      'source_assurance','member_supplied_unverified'),false);
  end if;
 end if;
 insert into private.mutation_receipts(owner_id,mutation_id,request_hash,response)
 values(u,mid,req_hash,response);
 return response;
end $function$

CREATE OR REPLACE FUNCTION public.dic_admin_push_bootstrap_key(p_public_key text, p_private_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing_key text; secret_id uuid;
begin
 perform pg_catalog.pg_advisory_xact_lock(1938,20261112);
 select r.vapid_public into existing_key
 from private.dic_admin_push_runtime r where r.singleton=true;
 if existing_key is not null then return existing_key; end if;
 if p_public_key !~ '^[A-Za-z0-9_-]{87}$' or p_private_key !~ '^[A-Za-z0-9_-]{43}$'
 then raise exception 'Invalid VAPID key material'; end if;
 secret_id:=vault.create_secret(
  p_private_key,'dic_admin_push_vapid_private_20261112',
  'Only service-role Edge Functions may decrypt this VAPID signing key');
 insert into private.dic_admin_push_runtime(singleton,vapid_public,vault_secret_id)
 values(true,p_public_key,secret_id);
 return p_public_key;
end;
$function$
